import { publish_and_unpublish_flows } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    formDeployed: Boolean,
    actionItem: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async deploy_workflow() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(publish_and_unpublish_flows, {
          input: {
            organization_id: data.organization.organization_id,
            workflow_id: this.actionItem.Info.workflow_id,
            workflow_deploy_status: this.actionItem.Info.workflow_deploy_status == "DEPLOY" ? "UNDEPLOY" : "DEPLOY"
          }
        }));
        var response = JSON.parse(result.data.publish_and_unpublish_flows);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
